{"command": "create", "path": "/workspace/src/args.rs", "file_text": "use std::collections::HashMap;
use std::process;

#[derive(Debug, Clone)]
pub struct OptionDef {
    pub key: String,
    pub full: String,
    pub abbr: Option<String>,
    pub flag: bool,
    pub list: bool,
    pub default: Option<serde_json::Value>,
    pub choices: Option<Vec<String>>,
    pub help: Option<String>,
    pub default_help: Option<String>,
    pub metavar: Option<String>,
    pub display_index: i32,
    pub callback: Option<fn(&HashMap<String, OptionDef>) -> String>,
    pub process: Option<fn(String) -> serde_json::Value>,
}

pub struct ArgParser {
    options: HashMap<String, OptionDef>,
    prepared: HashMap<String, String>,
}

struct Parsed {
    options: serde_json::Value,
    positional_arguments: Vec<String>,
}

impl ArgParser {
    pub fn new(options: Vec<OptionDef>) -> Self {
        let mut opts: HashMap<String, OptionDef> = HashMap::new();
        let mut prepared: HashMap<String, String> = HashMap::new();

        for mut opt in options {
            let key = opt.key.clone();
            if opt.full.is_empty() {
                opt.full = key.clone();
            }

            prepared.insert(format!("--{}", opt.full), key.clone());
            if let Some(ref abbr) = opt.abbr {
                prepared.insert(format!("-{}", abbr), key.clone());
            }
            if opt.flag {
                prepared.insert(format!("--no-{}", opt.full), key.clone());
            }
            opts.insert(key, opt);
        }

        // Add help option
        prepared.insert("--help".to_string(), "help".to_string());
        prepared.insert("-h".to_string(), "help".to_string());

        ArgParser { options: opts, prepared }
    }

    pub fn parse(&self, raw_args: &[String]) -> Result<(serde_json::Value, Vec<String>), (i32, String)> {
        let missing = serde_json::Value::Null;
        let mut parsed = serde_json::Map::new();
        let mut positional: Vec<String> = Vec::new();

        for (key, opt) in &self.options {
            if let Some(ref default) = opt.default {
                parsed.insert(key.clone(), default.clone());
            } else if opt.list {
                parsed.insert(key.clone(), serde_json::Value::Array(vec![]));
            }
        }

        let mut i = 0;
        while i < raw_args.len() {
            let arg = &raw_args[i];

            if is_option(arg) {
                let (opt_name, value_part) = if let Some(idx) = arg.find('=') {
                    (arg[..idx].to_string(), Some(arg[idx + 1..].to_string()))
                } else {
                    (arg.clone(), None)
                };

                let is_no_flag = opt_name.starts_with("--no-");
                let lookup_key = if is_no_flag {
                    opt_name.clone()
                } else {
                    opt_name.clone()
                };

                if let Some(key) = self.prepared.get(&lookup_key) {
                    // Handle help
                    if key == "help" {
                        return Err((0, self.get_help_text()));
                    }

                    if let Some(opt) = self.options.get(key) {
                        if let Some(cb) = opt.callback {
                            return Err((0, cb(&self.options)));
                        }

                        if opt.flag {
                            let val = if is_no_flag {
                                serde_json::Value::Bool(false)
                            } else if let Some(ref vp) = value_part {
                                serde_json::Value::Bool(vp == "1")
                            } else {
                                serde_json::Value::Bool(true)
                            };
                            parsed.insert(key.clone(), val);
                        } else {
                            let mut value = value_part;
                            if value.is_none() && i + 1 < raw_args.len() && !is_option(&raw_args[i + 1]) {
                                value = Some(raw_args[i + 1].clone());
                                i += 1;
                            }
                            if let Some(v) = value {
                                let processed = if let Some(ref p) = opt.process {
                                    p(v)
                                } else {
                                    serde_json::Value::String(v)
                                };
                                if opt.list {
                                    if let Some(arr) = parsed.get_mut(key) {
                                        if let serde_json::Value::Array(ref mut arr) = arr {
                                            arr.push(processed);
                                        }
                                    }
                                } else {
                                    parsed.insert(key.clone(), processed);
                                }
                            } else {
                                parsed.insert(key.clone(), missing.clone());
                            }
                        }
                    } else {
                        // Unknown option: pass through
                        let real_name = opt_name
                            .strip_prefix("--no-")
                            .or_else(|| opt_name.strip_prefix("--"))
                            .or_else(|| opt_name.strip_prefix('-'))
                            .unwrap_or(&opt_name)
                            .to_string();

                        let is_list = parsed.contains_key(&real_name)
                            && parsed.get(&real_name) != Some(&serde_json::Value::Bool(true));

                        if is_list {
                            if let Some(existing) = parsed.get(&real_name) {
                                let mut arr = if let serde_json::Value::Array(a) = existing {
                                    a.clone()
                                } else if existing == &serde_json::Value::Bool(true) {
                                    vec![]
                                } else {
                                    vec![existing.clone()]
                                };
                                if let Some(v) = value_part {
                                    arr.push(serde_json::Value::String(v));
                                }
                                parsed.insert(real_name.clone(), serde_json::Value::Array(arr));
                            }
                        } else if parsed.contains_key(&real_name) {
                            if let Some(v) = value_part {
                                let processed = try_parse_json(&v);
                                parsed.insert(real_name.clone(), processed);
                            }
                        } else {
                            let next_is_flag = i + 1 < raw_args.len() && is_option(&raw_args[i + 1]);
                            let value = if value_part.is_some() {
                                value_part.clone()
                            } else if next_is_flag {
                                None
                            } else if i + 1 < raw_args.len() {
                                let v = raw_args[i + 1].clone();
                                i += 1;
                                Some(v)
                            } else {
                                None
                            };
                            if let Some(v) = value {
                                parsed.insert(real_name.clone(), try_parse_json(&v));
                            } else {
                                parsed.insert(real_name.clone(), serde_json::Value::Bool(true));
                            }
                        }
                    }
                } else {
                    // Completely unknown, treat as pass-through flag
                    let cleaned = opt_name
                        .strip_prefix('-')
                        .unwrap_or(&opt_name)
                        .to_string();
                    if !parsed.contains_key(&cleaned) {
                        parsed.insert(cleaned, serde_json::Value::Bool(true));
                    }
                }
            } else {
                positional.push(if let Ok(n) = arg.parse::<i64>() {
                    n.to_string()
                } else {
                    arg.clone()
                });
            }
            i += 1;
        }

        // Check for missing values
        for (key, opt) in &self.options {
            if parsed.get(key) == Some(&missing) {
                return Err((
                    1,
                    format!("Missing value: --{} requires a value\n\n---\n\n{}",
                        opt.full, self.get_help_text())
                ));
            }
        }

        // Validate choices
        self.validate_choices(&parsed)?;

        let parsed_value = serde_json::Value::Object(parsed);

        Ok((parsed_value, positional))
    }

    fn validate_choices(&self, parsed: &serde_json::Map<String, serde_json::Value>) -> Result<(), (i32, String)> {
        let mut errors = Vec::new();
        for (key, opt) in &self.options {
            if let Some(ref choices) = opt.choices {
                if let Some(val) = parsed.get(key) {
                    let val_str = match val {
                        serde_json::Value::String(s) => s.clone(),
                        other => other.to_string(),
                    };
                    if !choices.contains(&val_str) {
                        errors.push(format!(
                            "Error: --{} must be one of the values {}",
                            opt.full,
                            choices.join(",")
                        ));
                    }
                }
            }
        }
        if !errors.is_empty() {
            Err((1, format!("{}\n\n---\n\n{}", errors.join("\n"), self.get_help_text())))
        } else {
            Ok(())
        }
    }

    pub fn get_help_text(&self) -> String {
        let mut sorted: Vec<&OptionDef> = self.options.values().collect();
        sorted.sort_by_key(|o| o.display_index);

        let mut text = String::from(
            "\nUsage: jscodeshift [OPTION]... PATH...\n  \
             or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...\n  \
             or:  jscodeshift [OPTION]... -t URL PATH...\n  \
             or:  jscodeshift [OPTION]... --stdin < file_list.txt\n\n\
             Apply transform logic in TRANSFORM_PATH (recursively) to every PATH.\n\
             If --stdin is set, each line of the standard input is used as a path.\n\n\
             Options:\n\
             \"...\" behind an option means that it can be supplied multiple times.\n\
             All options are also passed to the transformer, which means you can supply custom options that are not listed here.\n\n"
        );

        for opt in &sorted {
            text.push_str(&format_option(opt));
        }

        text
    }
}

fn is_option(value: &str) -> bool {
    value.starts_with('-') || value.starts_with("--")
}

fn try_parse_json(value: &str) -> serde_json::Value {
    if let Ok(v) = serde_json::from_str::<serde_json::Value>(value) {
        v
    } else {
        serde_json::Value::String(value.to_string())
    }
}

fn format_option(opt: &OptionDef) -> String {
    let mut text = String::from("  ");
    if let Some(ref abbr) = opt.abbr {
        text.push_str(&format!("-{}, ", abbr));
    } else {
        text.push_str("    ");
    }
    text.push_str(&format!("--{}{}", if opt.flag { "(no-)" } else { "" }, opt.full));
    if let Some(ref choices) = opt.choices {
        text.push_str(&format!("={}", choices.join("|")));
    } else if let Some(ref metavar) = opt.metavar {
        text.push_str(&format!("={}", metavar));
    }
    if opt.list {
        text.push_str(" ...");
    }
    if opt.default_help.is_some() || opt.default.is_some() || opt.help.is_some() {
        text.push_str("  ");
        if text.len() < 32 {
            for _ in text.len()..32 {
                text.push(' ');
            }
        }
        let text_len = text.len();
        if let Some(ref help) = opt.help {
            text.push_str(help);
        }
        if let Some(ref dh) = opt.default_help {
            if opt.help.is_some() {
                text.push('\n');
            }
            for _ in 0..text_len {
                text.push(' ');
            }
            text.push_str(&format!("(default: {})", dh));
        } else if let Some(ref def) = opt.default {
            if opt.help.is_some() {
                text.push('\n');
            }
            for _ in 0..text_len {
                text.push(' ');
            }
            text.push_str(&format!("(default: {})", def));
        }
    }
    text.push('\n');
    text
}

fn help_callback(options: &HashMap<String, OptionDef>) -> String {
    let parser = ArgParser::new(options.values().cloned().collect());
    parser.get_help_text()
}

