fn version_callback(_options: &HashMap<String, OptionDef>) -> String {
    // Attempt to get versions from node packages
    let babel_version = get_package_version("@babel/core");
    let babel_parser_version = get_package_version("@babel/parser");
    let flow_parser_version = get_package_version("flow-parser");
    let recast_version = get_package_version("recast");

    format!(
        "jscodeshift: {}\n - babel: {}\n - babylon: {}\n - flow: {}\n - recast: {}\n",
        env!("CARGO_PKG_VERSION"),
        babel_version.as_deref().unwrap_or("unknown"),
        babel_parser_version.as_deref().unwrap_or("unknown"),
        flow_parser_version.as_deref().unwrap_or("unknown"),
        recast_version.as_deref().unwrap_or("unknown"),
    )
}

fn get_package_version(name: &str) -> Option<String> {
    let output = std::process::Command::new("node")
        .args(["-e", &format!(
            "try {{ console.log(require('{}/package.json').version) }} catch(_) {{ console.log('unknown') }}",
            name
        )])
        .output()
        .ok()?;
    let version = String::from_utf8_lossy(&output.stdout).trim().to_string();
    if version.is_empty() || version == "unknown" {
        None
    } else {
        Some(version)
    }
}

pub mod tests {
    #[allow(unused_imports)]
    use super::*;

    #[test]
    fn test_basic_parsing() {
        let parser = build_parser();
        let args: Vec<String> = vec!["-t".into(), "mytransform.js".into(), "src/".into()];
        let (opts, pos) = parser.parse(&args).unwrap();
        assert_eq!(opts["transform"], "mytransform.js");
        assert_eq!(pos, vec!["src/"]);
    }

    #[test]
    fn test_default_values() {
        let parser = build_parser();
        let args: Vec<String> = vec!["-t".into(), "x.js".into(), "f.js".into()];
        let (opts, _pos) = parser.parse(&args).unwrap();
        assert_eq!(opts["parser"], "babel");
        assert_eq!(opts["dry"], false);
        assert_eq!(opts["babel"], true);
    }

    #[test]
    fn test_unknown_option_passthrough() {
        let parser = build_parser();
        let args: Vec<String> = vec!["-t".into(), "x.js".into(), "--foo".into(), "bar".into(), "f.js".into()];
        let (opts, pos) = parser.parse(&args).unwrap();
        assert_eq!(opts["foo"], "bar");
        assert_eq!(pos, vec!["f.js"]);
    }
}"}

{"command": "create", "path": "/workspace/src/ignore.rs", "file_text": "use std::fs;
use std::path::Path;
use std::sync::Mutex;

static MATCHERS: std::sync::LazyLock<Mutex<Vec<String>>> =
    std::sync::LazyLock::new(|| Mutex::new(Vec::new()));

pub fn add_ignore_from_input(input: &[String]) {
    let mut matchers = MATCHERS.lock().unwrap();
    for val in input {
        add_pattern(&mut matchers, val);
    }
}

pub fn add_ignore_from_file(paths: &[String]) {
    let mut matchers = MATCHERS.lock().unwrap();
    for config_path in paths {
        if let Ok(content) = fs::read_to_string(config_path) {
            for line in content.lines() {
                add_pattern(&mut matchers, line);
            }
        }
    }
}

pub fn should_ignore(path: &str) -> bool {
    let matchers = MATCHERS.lock().unwrap();
    if matchers.is_empty() {
        return false;
    }

    let normalized = path.trim_start_matches("./").trim_start_matches("../");
    // Also strip repeated leading traversal segments
    let mut n = normalized.to_string();
    while n.starts_with("./") || n.starts_with("../") {
        n = n.trim_start_matches("./").trim_start_matches("../").to_string();
    }

    let check = |p: &str| -> bool {
        for pattern in matchers.iter() {
            if glob_matches(pattern, p) {
                return true;
            }
        }
        false
    };

    check(path) || (n != path && check(&n))
}

fn add_pattern(matchers: &mut Vec<String>, val: &str) {
    let val = val.trim();
    if val.is_empty() || val.starts_with('#') {
        return;
    }
    let pattern = val.to_string();
    if !pattern.contains('/') {
        matchers.push(format!("**/{}", pattern));
    } else if pattern.ends_with('/') {
        matchers.push(format!("**/{}**", pattern));
        matchers.push(format!("{}**", pattern));
    }
    matchers.push(pattern);
}

fn glob_matches(pattern: &str, path: &str) -> bool {
    // Use glob crate for matching
    if let Ok(pat) = glob::Pattern::new(pattern) {
        pat.matches(path)
    } else {
        false
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty_matchers() {
        assert!(!should_ignore("src/foo.js"));
    }

    #[test]
    fn test_node_modules_ignore() {
        let _ = MATCHERS.lock().map(|mut m| {
            m.clear();
            m.push("**/node_modules/**".to_string());
        });
        assert!(should_ignore("node_modules/foo.js"));
        assert!(should_ignore("./node_modules/foo.js"));
        assert!(should_ignore("src/node_modules/bar.js"));
    }
}"}

{"command": "create", "path": "/workspace/src/worker.rs", "file_text": "use serde::{Deserialize, Serialize};
use std::io::{BufRead, BufReader, Write};
use std::process::{Child, ChildStdin, Command, Stdio};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;

#[derive(Serialize)]
struct WorkerMessage {
    files: Vec<String>,
    options: serde_json::Value,
}

#[derive(Deserialize, Debug)]
pub struct WorkerResponse {
    pub action: String,
    #[serde(default)]
    pub status: String,
    #[serde(default)]
    pub msg: String,
    #[serde(default)]
    pub name: String,
    #[serde(default)]
    pub quantity: f64,
    #[serde(default)]
    pub file: String,
}

pub struct Worker {
    child: Child,
    stdin: ChildStdin,
    stdout: BufReader<std::process::ChildStdout>,
}

impl Worker {
    pub fn spawn(transform_file: &str, babel: bool) -> Result<Self, std::io::Error> {
        let bridge_path = std::env::current_dir()
            .unwrap_or_else(|_| std::path::PathBuf::from("."))
            .join("bridge")
            .join("transform-host.js");

        let babel_arg = if babel { "babel" } else { "no-babel" };

        let mut child = Command::new("node")
            .arg(bridge_path.to_str().unwrap())
            .arg(transform_file)
            .arg(babel_arg)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .spawn()?;

        let stdin = child.stdin.take().unwrap();
        let stdout = BufReader::new(child.stdout.take().unwrap());

        Ok(Worker {
            child,
            stdin,
            stdout,
        })
    }

    pub fn send_batch(&mut self, files: Vec<String>, options: &serde_json::Value) -> Result<(), std::io::Error> {
        let msg = WorkerMessage {
            files,
            options: options.clone(),
        };
        let mut json = serde_json::to_string(&msg).unwrap();
        json.push('\n');
        self.stdin.write_all(json.as_bytes())?;
        self.stdin.flush()
    }

    pub fn read_responses(&mut self, running: Arc<AtomicBool>) -> Vec<WorkerResponse> {
        let mut responses = Vec::new();
        let mut line = String::new();

        // Read all available lines without blocking
        loop {
            match self.stdout.read_line(&mut line) {
                Ok(0) => {
                    running.store(false, Ordering::SeqCst);
                    break;
                }
                Ok(_) => {
                    let trimmed = line.trim().to_string();
                    line.clear();
                    if trimmed.is_empty() {
                        continue;
                    }
                    if let Ok(resp) = serde_json::from_str::<WorkerResponse>(&trimmed) {
                        let action = resp.action.clone();
                        responses.push(resp);
                        if action == "free" || action == "disconnect" {
                            break;
                        }
                    }
                }
                Err(_) => {
                    running.store(false, Ordering::SeqCst);
                    break;
                }
            }
        }
        responses
    }

    pub fn wait(mut self) -> std::io::Result<()> {
        drop(self.stdin);
        self.child.wait()?;
        Ok(())
    }
}"}

