// This is the bridge that loads and executes jscodeshift transforms.
// It communicates with the Rust CLI via JSON lines over stdin/stdout.
// It is spawned once per worker process.

const fs = require('graceful-fs');
const writeFileAtomic = require('write-file-atomic');
const getParser = require('../codebase/src/getParser');
const jscodeshift = require('../codebase/src/core');

let presetEnv;
try {
  presetEnv = require('@babel/preset-env');
} catch (_) {}

let transform;
let parserFromTransform;

const transformFile = process.argv[2];
const babelFlag = process.argv[3];

function notify(data) {
  process.stdout.write(JSON.stringify(data) + '\n');
}

if (babelFlag === 'babel') {
  const presets = [];
  if (presetEnv) {
    presets.push([
      presetEnv.default,
      { targets: { node: true } },
    ]);
  }
  presets.push(
    /\.tsx?$/.test(transformFile) ?
      require('@babel/preset-typescript').default :
      require('@babel/preset-flow').default
  );

  require('@babel/register')({
    configFile: false,
    babelrc: false,
    presets,
    plugins: [
      require('@babel/plugin-transform-class-properties').default,
      require('@babel/plugin-transform-nullish-coalescing-operator').default,
      require('@babel/plugin-transform-optional-chaining').default,
      require('@babel/plugin-transform-modules-commonjs').default,
      require('@babel/plugin-transform-private-methods').default,
    ],
    extensions: ['.js', '.jsx', '.es6', '.es', '.mjs', '.cjs', '.ts', '.tsx'],
    ignore: [
      /@babel\/parser/,
      /\/flow-parser\//,
      /\/recast\//,
      /\/ast-types\//,
    ],
  });
}

const module_ = require(transformFile);
transform = typeof module_.default === 'function' ? module_.default : module_;
if (module_.parser) {
  parserFromTransform = typeof module_.parser === 'string' ?
    getParser(module_.parser) :
    module_.parser;
}

function prepareJscodeshift(options) {
  const parser = parserFromTransform ||
    getParser(options.parser, options.parserConfig);
  return jscodeshift.withParser(parser);
}

function processFile(file, options, callback) {
  fs.readFile(file, function(err, source) {
    if (err) {
      notify({ action: 'status', status: 'error', msg: file + ' File error: ' + err });
      callback();
      return;
    }
    source = source.toString();
    try {
      const api = prepareJscodeshift(options);
      Promise.resolve(transform(
        { path: file, source: source },
        {
          j: api,
          jscodeshift: api,
          stats: options.dry ? function(name, qty) {
            notify({ action: 'update', name: name, quantity: qty || 1 });
          } : function() {},
          report: function(msg) {
            notify({ action: 'report', file: file, msg: msg });
          },
        },
        options
      )).then(function(out) {
        if (!out || out === source) {
          notify({ action: 'status', status: out ? 'nochange' : 'skip', msg: file });
          callback();
          return;
        }
        if (options.print) {
          console.log(out);
        }
        if (!options.dry) {
          writeFileAtomic(file, out, function(err) {
            if (err) {
              notify({ action: 'status', status: 'error', msg: file + ' File writer error: ' + err });
            } else {
              notify({ action: 'status', status: 'ok', msg: file });
            }
            callback();
          });
        } else {
          notify({ action: 'status', status: 'ok', msg: file });
          callback();
        }
      }).catch(function(err) {
        const msg = 'Transformation error (' + err.message.replace(/\n/g, ' ') + ')';
        const trace = (err.stack || '').split('\n')
          .filter(function(line) { return line.indexOf(__filename) === -1; })
          .join('\n');
        notify({ action: 'status', status: 'error', msg: file + ' ' + msg + '\n' + trace });
        callback();
      });
    } catch (err) {
      const msg = 'Transformation error (' + err.message.replace(/\n/g, ' ') + ')';
      const trace = (err.stack || '').split('\n')
        .filter(function(line) { return line.indexOf(__filename) === -1; })
        .join('\n');
      notify({ action: 'status', status: 'error', msg: file + ' ' + msg + '\n' + trace });
      callback();
    }
  });
}

function processFiles(files, callback) {
  let i = 0;
  function next() {
    if (i >= files.length) {
      callback();
      return;
    }
    processFile(files[i], options_, function() {
      i++;
      next();
    });
  }
  next();
}

var options_;

process.stdin.on('data', function(data) {
  const lines = data.toString().trim().split('\n');
  for (const line of lines) {
    if (!line.trim()) continue;
    try {
      const msg = JSON.parse(line);
      if (msg.files && msg.options) {
        options_ = msg.options;
        processFiles(msg.files, function() {
          notify({ action: 'free' });
        });
      }
    } catch(_) {}
  }
});"}

