{"command": "create", "path": "/workspace/src/runner.rs", "file_text": "use crate::ignore;
use crate::worker::Worker;
use std::collections::HashMap;
use std::fs;
use std::io::{self, BufRead, Write};
use std::path::Path;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::time::Instant;

const CHUNK_SIZE: usize = 50;

pub fn run(transform_file: &str, paths: Vec<String>, options: &serde_json::Value) -> i32 {
    let cpus = options["cpus"]
        .as_i64()
        .map(|c| {
            let available = std::cmp::max(num_cpus::get() as i64 - 1, 1);
            std::cmp::min(available, c) as usize
        })
        .unwrap_or_else(|| std::cmp::max(num_cpus::get().saturating_sub(1), 1));

    let extensions: Option<Vec<String>> = options["extensions"]
        .as_str()
        .map(|s| s.split(',').map(|e| format!(".{}", e.trim())).collect());

    let silent = options["silent"].as_bool().unwrap_or(false);
    let dry = options["dry"].as_bool().unwrap_or(false);
    let run_in_band = options["runInBand"].as_bool().unwrap_or(false);
    let fail_on_error = options["failOnError"].as_bool().unwrap_or(false);
    let verbose = options["verbose"].as_i64().unwrap_or(0);
    let print = options["print"].as_bool().unwrap_or(false);

    // Setup ignore rules
    if let Some(patterns) = options["ignorePattern"].as_array() {
        let vals: Vec<String> = patterns.iter().map(|v| v.as_str().unwrap_or("").to_string()).collect();
        if !vals.is_empty() {
            ignore::add_ignore_from_input(&vals);
        }
    }
    if let Some(configs) = options["ignoreConfig"].as_array() {
        let vals: Vec<String> = configs.iter().map(|v| v.as_str().unwrap_or("").to_string()).collect();
        if !vals.is_empty() {
            ignore::add_ignore_from_file(&vals);
        }
    }
    if options["gitignore"].as_bool().unwrap_or(false) {
        if let Ok(cwd) = std::env::current_dir() {
            let gitignore = cwd.join(".gitignore");
            if gitignore.exists() {
                ignore::add_ignore_from_file(&[gitignore.to_string_lossy().to_string()]);
            }
        }
    }

    // Handle URL transform
    let actual_transform_file: String;
    if transform_file.starts_with("http://") || transform_file.starts_with("https://") {
        // Download to temp file
        let tmp_dir = std::env::temp_dir();
        let filename = Path::new(transform_file)
            .file_name()
            .map(|n| n.to_string_lossy().to_string())
            .unwrap_or_else(|| "jscodeshift_transform.js".to_string());
        let tmp_path = tmp_dir.join(format!("jscodeshift_{}", filename));

        match download_file(transform_file, &tmp_path) {
            Ok(()) => {
                actual_transform_file = tmp_path.to_string_lossy().to_string();
            }
            Err(e) => {
                eprintln!("Error downloading transform: {}", e);
                return 1;
            }
        }
    } else {
        if !Path::new(transform_file).exists() {
            let msg = format!(
                "\x1b[41m\x1b[37mERROR\x1b[0m Transform file {} does not exist \n",
                transform_file
            );
            eprint!("{}", msg);
            return 1;
        }
        actual_transform_file = transform_file.to_string();
    }

    // Discover files
    let files = discover_files(&paths, &extensions);
    if files.is_empty() {
        println!("No files selected, nothing to do. ");
        return 0;
    }

    if !silent {
        println!("Processing {} files... ", files.len());
        if !run_in_band {
            println!("Spawning {} workers...", if run_in_band { 1 } else { cpus });
        }
        if dry {
            println!("\x1b[32mRunning in dry mode, no files will be written! \x1b[0m");
        }
    }

    let start_time = Instant::now();
    let num_workers = if run_in_band { 1 } else { std::cmp::min(files.len(), cpus) };
    let chunk_size = if num_workers > 1 {
        std::cmp::min((files.len() + num_workers - 1) / num_workers, CHUNK_SIZE)
    } else {
        files.len()
    };

    let babel = options["babel"].as_bool().unwrap_or(true);

    let mut file_counters: HashMap<String, u64> = HashMap::new();
    file_counters.insert("error".into(), 0);
    file_counters.insert("ok".into(), 0);
    file_counters.insert("nochange".into(), 0);
    file_counters.insert("skip".into(), 0);

    let mut stats_counter: HashMap<String, f64> = HashMap::new();
    let mut idx: usize = 0;

    let files_arc = Arc::new(files);

    // Spawn workers
    let mut workers: Vec<Worker> = Vec::new();
    for _ in 0..num_workers {
        match Worker::spawn(&actual_transform_file, babel) {
            Ok(w) => workers.push(w),
            Err(e) => {
                eprintln!("Error spawning worker: {}", e);
                return 1;
            }
        }
    }

    // Send initial batches
    let mut active = num_workers;
    let running = Arc::new(AtomicBool::new(true));

    for worker in &mut workers {
        let batch: Vec<String> = files_arc[idx..std::cmp::min(idx + chunk_size, files_arc.len())].to_vec();
        idx = std::cmp::min(idx + chunk_size, files_arc.len());
        let _ = worker.send_batch(batch, options);
    }

    // Process responses
    while active > 0 && running.load(Ordering::SeqCst) {
        for worker in &mut workers {
            let responses = worker.read_responses(running.clone());
            for resp in responses {
                match resp.action.as_str() {
                    "status" => {
                        *file_counters.entry(resp.status.clone()).or_insert(0) += 1;
                        let emoji = match resp.status.as_str() {
                            "ok" => "\x1b[42m\x1b[37m OKK \x1b[0m ",
                            "nochange" => "\x1b[43m\x1b[37m NOC \x1b[0m ",
                            "skip" => "\x1b[43m\x1b[37m SKIP \x1b[0m ",
                            "error" => "\x1b[41m\x1b[37m ERR \x1b[0m ",
                            _ => "",
                        };
                        let verbosity = match resp.status.as_str() {
                            "ok" => 2,
                            "nochange" | "skip" => 1,
                            _ => 0,
                        };
                        if verbose >= verbosity {
                            let msg = if resp.msg.ends_with('\n') {
                                resp.msg.clone()
                            } else {
                                format!("{}\n", resp.msg)
                            };
                            print!("{}", format!("{}{}", emoji, msg));
                            let _ = io::stdout().flush();
                        }
                    }
                    "update" => {
                        *stats_counter.entry(resp.name).or_insert(0.0) += resp.quantity;
                    }
                    "report" => {
                        let msg = if resp.msg.ends_with('\n') {
                            resp.msg.clone()
                        } else {
                            format!("{}\n", resp.msg)
                        };
                        print!(
                            "{}",
                            format!(
                                "\x1b[44m\x1b[37m REP \x1b[0m{} {}\n",
                                resp.file, msg
                            )
                        );
                        let _ = io::stdout().flush();
                    }
                    "free" => {
                        if idx < files_arc.len() {
                            let next_batch: Vec<String> = files_arc[idx..std::cmp::min(idx + chunk_size, files_arc.len())].to_vec();
                            idx = std::cmp::min(idx + chunk_size, files_arc.len());
                            if !silent && !run_in_band {
                                println!(
                                    "Sending {} files to free worker...",
                                    std::cmp::min(chunk_size, files_arc.len().saturating_sub(idx))
                                );
                            }
                            let _ = worker.send_batch(next_batch, options);
                        } else {
                            active -= 1;
                        }
                    }
                    _ => {}
                }
            }
        }
    }

    // Wait for all workers
    for worker in workers {
        let _ = worker.wait();
    }

    let elapsed = start_time.elapsed();
    let time_elapsed = format!("{:.3}", elapsed.as_secs_f64());

    if !silent {
        println!("All done. ");
        println!("Results: ");
        println!(
            "\x1b[31m{} errors\x1b[0m\n\x1b[33m{} unmodified\x1b[0m\n\x1b[33m{} skipped\x1b[0m\n\x1b[32m{} ok\x1b[0m",
            file_counters.get("error").unwrap_or(&0),
            file_counters.get("nochange").unwrap_or(&0),
            file_counters.get("skip").unwrap_or(&0),
            file_counters.get("ok").unwrap_or(&0),
        );

        if !stats_counter.is_empty() {
            println!("\x1b[34mStats: \x1b[0m");
            let mut names: Vec<&String> = stats_counter.keys().collect();
            names.sort();
            for name in names {
                println!("{}: {}", name, stats_counter[name]);
            }
        }

        println!("Time elapsed: {}seconds ", time_elapsed);

        if fail_on_error && *file_counters.get("error").unwrap_or(&0) > 0 {
            return 1;
        }
    }

    0
}

fn discover_files(paths: &[String], extensions: &Option<Vec<String>>) -> Vec<String> {
    let mut result = Vec::new();

    for path_str in paths {
        let path = Path::new(path_str);
        if path.is_dir() {
            collect_dir_files(path, &mut result, extensions);
        } else if path.is_file() {
            if !ignore::should_ignore(path_str) {
                if let Some(ref exts) = extensions {
                    if let Some(ext) = path.extension() {
                        let ext_str = format!(".{}", ext.to_string_lossy());
                        if exts.contains(&ext_str) {
                            result.push(path_str.clone());
                        }
                    }
                } else {
                    result.push(path_str.clone());
                }
            }
        } else {
            eprintln!("Skipping path {} which does not exist. ", path_str);
        }
    }

    result
}

fn collect_dir_files(dir: &Path, result: &mut Vec<String>, extensions: &Option<Vec<String>>) {
    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            let path_str = path.to_string_lossy().to_string();

            if ignore::should_ignore(&path_str) {
                continue;
            }

            if path.is_dir() {
                collect_dir_files(&path, result, extensions);
            } else if path.is_file() {
                if let Some(ref exts) = extensions {
                    if let Some(ext) = path.extension() {
                        let ext_str = format!(".{}", ext.to_string_lossy());
                        if exts.contains(&ext_str) {
                            result.push(path_str);
                        }
                    }
                } else {
                    result.push(path_str);
                }
            }
        }
    }
}

fn download_file(url: &str, dest: &Path) -> Result<(), Box<dyn std::error::Error>> {
    let response = ureq::get(url).call()?;
    let mut body = Vec::new();
    response.into_reader().read_to_end(&mut body)?;
    fs::write(dest, body)?;
